from pathlib import Path
import sqlite3,json
home=Path('.local/hermes-lab/home')
for p in home.rglob('state.db'):
 db=sqlite3.connect(f'file:{p.resolve()}?mode=ro',uri=True);db.row_factory=sqlite3.Row
 try:
  rows=db.execute("SELECT id,source,user_id,session_key,chat_id,chat_type,thread_id,origin_json,started_at,ended_at,profile_name,transport_profile FROM sessions WHERE chat_id=? AND thread_id=?",('D0C6EAXPKEE','1791586074.361539')).fetchall()
  ids=[r['session_id'] for r in db.execute("SELECT session_id FROM messages WHERE platform_message_id IN (?,?)",('1791586074.361539','1791619675.650219'))]
  if ids and not rows: rows=db.execute('SELECT id,source,user_id,session_key,chat_id,chat_type,thread_id,origin_json,started_at,ended_at,profile_name,transport_profile FROM sessions WHERE id IN ('+','.join('?' for _ in ids)+')',ids).fetchall()
  for r in rows: print('SESSION',p,json.dumps(dict(r)))
 except sqlite3.Error:continue
for p in home.rglob('*.sqlite3'):
 print('SQLITE3',p)
PY

